# Fact records for future rule-based inference. Each known item is represented as a fact.
FACTS = []
for key, data in INGREDIENTS.items():
    FACTS.append({"id":"ING_"+key.upper(),"name":key,"type":"ingredient","status":data["status"],"group":data["group"],"aliases":data.get("aliases",[]),"reason":data["reason"]})
for code, data in E_CODES.items():
    FACTS.append({"id":"ECODE_"+code.replace(".","_"),"name":code,"type":"e_code","status":data["status"],"group":"e_code","aliases":[data["name"]]+data.get("aliases",[]),"reason":data["reason"]})

def knowledge_base_summary():
    return {
        "ingredient_records": len(INGREDIENTS),
        "e_code_records": len(E_CODES),
        "total_facts": len(FACTS),
        "halal": sum(1 for f in FACTS if f["status"] == "HALAL"),
        "haram": sum(1 for f in FACTS if f["status"] == "HARAM"),
        "mashook": sum(1 for f in FACTS if f["status"] == "MASHKOOK"),
    }
